"use client";

import { useCallback, useEffect, useState } from "react";

type Ticket = { id: string; number: string; subject: string; status: string; priority: string; messages: { id: string; body: string; kind: string; createdAt: string; author: { name: string; role: string } }[]; rating: { rating: number; comment: string | null } | null };

export function SupportConversation({ ticketId }: { ticketId: string }) {
  const [ticket, setTicket] = useState<Ticket | null>(null); const [error, setError] = useState(""); const [sending, setSending] = useState(false); const [message, setMessage] = useState("");
  const load = useCallback(async () => { const response = await fetch(`/api/support/tickets/${ticketId}`, { cache: "no-store" }); const data = await response.json(); if (!response.ok) { setError(data.error || "Unable to load ticket."); return; } setTicket(data.ticket); }, [ticketId]);
  useEffect(() => { void load(); }, [load]);
  async function reply(event: React.FormEvent) { event.preventDefault(); if (!message.trim()) return; setSending(true); const response = await fetch(`/api/support/tickets/${ticketId}/messages`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ body: message }) }); const data = await response.json(); setSending(false); if (!response.ok) { setError(data.error || "Unable to send message."); return; } setMessage(""); void load(); }
  async function rate(event: React.FormEvent<HTMLFormElement>) { event.preventDefault(); const form = new FormData(event.currentTarget); const response = await fetch(`/api/support/tickets/${ticketId}/rating`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ rating: Number(form.get("rating")), comment: form.get("comment") || undefined }) }); const data = await response.json(); if (!response.ok) { setError(data.error || "Unable to save rating."); return; } void load(); }
  if (error && !ticket) return <p role="alert" className="mt-6 rounded-lg bg-red-50 p-4 text-red-700">{error}</p>;
  if (!ticket) return <p className="mt-6 text-slate-600">Loading ticket…</p>;
  return <section className="mt-8"><header className="rounded-2xl border bg-white p-6"><p className="text-sm font-semibold text-blue-700">{ticket.number}</p><h1 className="mt-2 text-3xl font-bold">{ticket.subject}</h1><p className="mt-2 text-sm text-slate-600">{ticket.status.replace(/_/g, " ")} · {ticket.priority}</p></header><div className="mt-5 space-y-3">{ticket.messages.map((entry) => <article key={entry.id} className={`rounded-xl border p-4 ${entry.kind === "AGENT_REPLY" ? "border-blue-200 bg-blue-50" : "bg-white"}`}><p className="font-semibold text-slate-900">{entry.author.name}</p><p className="mt-2 whitespace-pre-wrap text-slate-700">{entry.body}</p><p className="mt-2 text-xs text-slate-500">{new Date(entry.createdAt).toLocaleString()}</p></article>)}</div>{ticket.status !== "CLOSED" ? <form onSubmit={(event) => void reply(event)} className="mt-5 rounded-xl border bg-white p-5"><label className="font-medium">Reply<textarea value={message} onChange={(event) => setMessage(event.target.value)} maxLength={8000} rows={5} className="mt-2 w-full rounded-lg border p-3" /></label><button disabled={sending} className="mt-3 rounded-lg bg-blue-700 px-4 py-2 font-semibold text-white disabled:opacity-60">{sending ? "Sending…" : "Send reply"}</button></form> : null}{["RESOLVED", "CLOSED"].includes(ticket.status) && !ticket.rating ? <form onSubmit={(event) => void rate(event)} className="mt-5 rounded-xl border bg-white p-5"><h2 className="font-bold">Rate support</h2><label className="mt-3 block">Rating<select name="rating" className="mt-1 w-full rounded border p-2">{[5, 4, 3, 2, 1].map((value) => <option key={value} value={value}>{value}</option>)}</select></label><label className="mt-3 block">Comment (optional)<textarea name="comment" maxLength={1000} rows={3} className="mt-1 w-full rounded border p-2" /></label><button className="mt-3 rounded-lg border px-4 py-2 font-semibold">Submit rating</button></form> : null}{error ? <p role="alert" className="mt-4 text-red-700">{error}</p> : null}</section>;
}
